def strongest_by_kind(roster):
    # map each kind to the name of its highest-attack record
    pass

exercises.solution:
def strongest_by_kind(roster):
    best = {}
    for p in roster:
        if p['kind'] not in best or p['attack'] > best[p['kind']]['attack']:
            best[p['kind']] = p
    return {k: p['name'] for k, p in best.items()}

