def average_attack_by_kind(roster):
    # map each kind to its rounded average attack
    pass

exercises.solution:
def average_attack_by_kind(roster):
    sums, counts = {}, {}
    for p in roster:
        sums[p['kind']] = sums.get(p['kind'], 0) + p['attack']
        counts[p['kind']] = counts.get(p['kind'], 0) + 1
    return {k: round(sums[k] / counts[k]) for k in sums}

