def kind_with_highest_average_attack(roster):
    # return the kind with the greatest average attack
    pass

exercises.solution:
def kind_with_highest_average_attack(roster):
    sums, counts = {}, {}
    for p in roster:
        sums[p['kind']] = sums.get(p['kind'], 0) + p['attack']
        counts[p['kind']] = counts.get(p['kind'], 0) + 1
    best, best_avg = None, float('-inf')
    for k in sorted(sums):
        avg = sums[k] / counts[k]
        if avg > best_avg:
            best_avg, best = avg, k
    return best

exercises.starter:
def attack_share_by_kind(roster):
    # map each kind to its percentage share of the total attack
    pass

exercises.solution:
def attack_share_by_kind(roster):
    total = sum(p['attack'] for p in roster)
    sums = {}
    for p in roster:
        sums[p['kind']] = sums.get(p['kind'], 0) + p['attack']
    return {k: round(v * 100 / total, 1) for k, v in sums.items()}

exercises.starter:
def battle_roles(roster):
    # count the records in each of the four roles
    pass

exercises.solution:
def battle_roles(roster):
    roles = {'elite': 0, 'attacker': 0, 'defender': 0, 'rookie': 0}
    for p in roster:
        strong = p['attack'] >= 50
        tough = p['defense'] >= 50
        if strong and tough:
            roles['elite'] += 1
        elif strong:
            roles['attacker'] += 1
        elif tough:
            roles['defender'] += 1
        else:
            roles['rookie'] += 1
    return roles
